.bd-callout {
  padding: 1.25rem;
  margin-top: 1.25rem;
  margin-bottom: 1.25rem;
  border: 0;
  border-left: 2px solid #fb383b;
  border-left-color: #fb383b;
  border-left-width: 1px;
  border-left-width: .25rem;
  border-radius: .25rem;
}

iframe {
    width: 100%;
}
section#section-contact-address {
    position: relative;
}

.address-box {
    border-width: 0px 01px 0px 0px;
    border-color: #EEEEEE;
    transition: background 0.3s, border 0.3s, border-radius 0.3s, box-shadow 0.3s;
    padding: 30px 25px 20px 25px;
    background: #F1F2F6;
    padding: 20px;
    display: -webkit-box;
    display: flex;
    -webkit-box-flex: 1;
    flex: 1;
    -webkit-box-pack: justify;
    justify-content: space-between;
    -webkit-box-orient: vertical;
    -webkit-box-direction: normal;
    flex-direction: column;
}


img.detail-icon.deatil-side {
    float: left;
    margin: 5px 9px 0 0;
}
.address-eie {
    display: -webkit-box;
}
section#section-contact-address {
    margin-top: -157px;
}
.address-box.bg-white:hover {
    background:  #F1F2F6 !important;
}

.address-box h6 {
    font-weight: 700;
}

.card-header.main {
    background: #333e45;
    margin: 0 0 20px 0;
    color:#fff;
    padding: 0;
    border: none;
    border-radius: 0;
}
button.btn.btn-link.collape-btn {
    color: #fff;
    text-decoration: none;
    width: 100%;
    text-align: left;
        position: relative;
    overflow: hidden;
        border: none;
    border-radius: 0;
    padding: 15px;

}
.card.card-main {
    border: none;
}

.collape-btn:after{
    position: absolute;
    content: '\2212';
    right: 15px;
    top: 50%;
    -webkit-transform: translateY(-50%);
    transform: translateY(-50%);
}
/*.collape-btn.collapsed :after {*/
/*    content: "\2212";*/
/*}*/

.collapsed.collape-btn:after {
    content: '\002B';
    font-weight: bolder;
}
.collape-btn .active:after{
    
}

.collape-btn:before {
    position: absolute;
    content: '';
    background: #fb383b;
    -webkit-transform: skew(-35deg);
    transform: skew(-35deg);
    height: 100%;
    width: 50%;
    left: 90%;
    top: 0;
}


.collapsible {
  background-color: #282828;
  color: white;
  cursor: pointer;
  padding: 18px;
  width: 100%;
  border: none;
  text-align: left;
  outline: none;
  font-size: 15px;
  display: block;
  position: relative;
  overflow: hidden;
}
.collapse-detail {
    padding: 10px 0;
}
button.collapsible:after {
    content: '\002B';
    color: #fff;
    font-weight: bold;
    float: right;
    margin-left: 5px;
    position: relative;
}
button.collapsible.active:after {
    content: "\2212";
}
button.collapsible:before{
    position: absolute;
    content: '';
    background: #fb383b;
    -webkit-transform: skew(-35deg);
    transform: skew(-35deg);
    height: 100%;
    width: 50%;
    left: 90%;
    top: 0;
}

.content {
  padding: 0 18px;
  max-height: 0;
  overflow: hidden;
  transition: max-height 0.2s ease-out;
  background-color: #f1f1f1;
  margin: 0 0 20px 0;
}



.collapse-detail h6 {
    font-weight: 700;
}


.detail-icon {
    max-width: 15px;
    /* margin: 0; */
}
.call-detail a{
    font-size: 15px;
    line-height: 30px;
    text-align: justify;
    color: #636361;
    letter-spacing: 0.5px;
    font-family: hind;
    font-weight: 400;
}

#print-message-field{
    margin-top:11%;
}
.banner-up-img{
    overflow: hidden;
    z-index: 1;
    position: absolute;
    bottom:2%;
    left: 25%;
    width: 67.25vh;
    height: 80vh;
    box-shadow: None!important;
    /* -webkit-clip-path: polygon(0 0, 100% 0, 100% 100%, 0 100%, 0 0, 6vh 0, 6vh 61vh, 44vh 61vh, 44vh 6vh, 6vh 6vh); */
    /* clip-path: polygon(50% 0%, 100% 50%, 50% 100%, 0% 50%); */

    -webkit-transition-timing-function: ease-in-out;
    transition-timing-function: ease-in-out
}

